version: "3.9"

# Mirrors the production topology: the API runs as 3 stateless replicas behind
# the nginx load balancer. Anything that must be coordinated across requests
# has to live in Postgres, not in process memory.
services:
  api:
    build: .
    deploy:
      replicas: 3
    environment:
      DATABASE_URL: postgres://ledgerly:ledgerly@db:5432/ledgerly
      JWT_SECRET: ${JWT_SECRET}
      PAYMENT_WEBHOOK_SECRET: ${PAYMENT_WEBHOOK_SECRET}
      NODE_ENV: production
    depends_on:
      - db

  lb:
    image: nginx:1.25
    ports:
      - "8080:80"
    volumes:
      - ./deploy/nginx.conf:/etc/nginx/nginx.conf:ro
    depends_on:
      - api

  db:
    image: postgres:16
    environment:
      POSTGRES_USER: ledgerly
      POSTGRES_PASSWORD: ledgerly
      POSTGRES_DB: ledgerly
    volumes:
      - pgdata:/var/lib/postgresql/data

volumes:
  pgdata:
import { z } from "zod";

const schema = z.object({
  DATABASE_URL: z.string().url(),
  JWT_SECRET: z.string().min(16),
  PAYMENT_WEBHOOK_SECRET: z.string().min(8),
  PORT: z.coerce.number().default(3000),
  LOG_LEVEL: z.enum(["debug", "info", "warn", "error"]).default("info"),
  ORDER_RETENTION_DAYS: z.coerce.number().int().positive().default(730),
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
});

export const env = schema.parse(process.env);
import { Router } from "express";
import { z } from "zod";
import { pool, withTransaction } from "../db/pool.js";
import { reserveStock } from "../services/inventory.js";
import { requireAdmin } from "../middleware/auth.js";

export const ordersRouter = Router();

const createOrderSchema = z.object({
  customer_id: z.number().int().positive().optional(),
  items: z
    .array(
      z.object({
        product_id: z.number().int().positive(),
        quantity: z.number().int().positive().max(1000),
      }),
    )
    .min(1),
});

ordersRouter.get("/", async (req, res) => {
  // Returns every order visible to the caller. There is no pagination yet;
  // the web table (web/src/components/OrderTable.tsx) renders the full list.
  const isAdmin = req.user!.role === "admin";
  const { rows } = isAdmin
    ? await pool.query("SELECT * FROM orders ORDER BY created_at DESC")
    : await pool.query("SELECT * FROM orders WHERE user_id = $1 ORDER BY created_at DESC", [req.user!.id]);
  res.json({ orders: rows });
});

ordersRouter.get("/:id", async (req, res) => {
  const id = Number(req.params.id);
  const { rows } = await pool.query("SELECT * FROM orders WHERE id = $1", [id]);
  const order = rows[0];
  if (!order) return res.status(404).json({ error: "not_found" });
  if (req.user!.role !== "admin" && order.user_id !== req.user!.id) {
    return res.status(404).json({ error: "not_found" });
  }
  const items = await pool.query("SELECT * FROM order_items WHERE order_id = $1", [id]);
  return res.json({ order, items: items.rows });
});

ordersRouter.post("/", async (req, res) => {
  const parsed = createOrderSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: "invalid_body", details: parsed.error.flatten() });

  const { items, customer_id } = parsed.data;

  const order = await withTransaction(async (client) => {
    let totalCents = 0;
    const priced: Array<{ product_id: number; quantity: number; unit_price_cents: number }> = [];

    for (const item of items) {
      const product = await reserveStock(client, item.product_id, item.quantity);
      totalCents += product.unit_price_cents * item.quantity;
      priced.push({ ...item, unit_price_cents: product.unit_price_cents });
    }

    const inserted = await client.query(
      "INSERT INTO orders (user_id, customer_id, total_cents) VALUES ($1, $2, $3) RETURNING *",
      [req.user!.id, customer_id ?? null, totalCents],
    );
    const order = inserted.rows[0];

    for (const p of priced) {
      await client.query(
        "INSERT INTO order_items (order_id, product_id, quantity, unit_price_cents) VALUES ($1, $2, $3, $4)",
        [order.id, p.product_id, p.quantity, p.unit_price_cents],
      );
    }
    return order;
  });

  res.status(201).json({ order });
});

ordersRouter.post("/:id/cancel", requireAdmin, async (req, res) => {
  const id = Number(req.params.id);
  const { rowCount } = await pool.query(
    "UPDATE orders SET status = 'cancelled', updated_at = now() WHERE id = $1 AND status IN ('pending', 'overdue')",
    [id],
  );
  if (!rowCount) return res.status(409).json({ error: "not_cancellable" });
  return res.json({ ok: true });
});
import { describe, it, expect, vi, beforeEach } from "vitest";

vi.mock("../src/db/pool.js", () => ({
  pool: { query: vi.fn() },
  withTransaction: vi.fn(async (fn: (c: unknown) => Promise<unknown>) => fn({ query: vi.fn() })),
}));

import request from "supertest";
import { createApp } from "../src/server.js";
import { signAccessToken } from "../src/middleware/auth.js";
import { pool } from "../src/db/pool.js";

const memberToken = signAccessToken({ id: 7, email: "m@example.com", role: "member" });
const adminToken = signAccessToken({ id: 1, email: "a@example.com", role: "admin" });

describe("GET /orders", () => {
  beforeEach(() => vi.mocked(pool.query).mockReset());

  it("scopes to the caller for members", async () => {
    vi.mocked(pool.query).mockResolvedValueOnce({ rows: [] } as never);
    const res = await request(createApp()).get("/orders").set("authorization", `Bearer ${memberToken}`);
    expect(res.status).toBe(200);
    expect(vi.mocked(pool.query).mock.calls[0][0]).toMatch(/WHERE user_id = \$1/);
  });

  it("returns everything for admins", async () => {
    vi.mocked(pool.query).mockResolvedValueOnce({ rows: [] } as never);
    const res = await request(createApp()).get("/orders").set("authorization", `Bearer ${adminToken}`);
    expect(res.status).toBe(200);
    expect(vi.mocked(pool.query).mock.calls[0][0]).not.toMatch(/WHERE/);
  });

  it("rejects missing tokens", async () => {
    const res = await request(createApp()).get("/orders");
    expect(res.status).toBe(401);
  });
});

describe("POST /orders/:id/cancel", () => {
  it("requires admin", async () => {
    const res = await request(createApp()).post("/orders/5/cancel").set("authorization", `Bearer ${memberToken}`);
    expect(res.status).toBe(403);
  });
});
